import{_ as o,o as i,c as l,ae as a}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Cross-Repo Rollout Map (Phase 0-3)","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/20260226-helios-market-research/13_CROSS_REPO_ROLLOUT_MAP.md","filePath":"sessions/20260226-helios-market-research/13_CROSS_REPO_ROLLOUT_MAP.md"}'),t={name:"sessions/20260226-helios-market-research/13_CROSS_REPO_ROLLOUT_MAP.md"};function r(s,e,n,c,d,u){return i(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="cross-repo-rollout-map-phase-0-3" tabindex="-1">Cross-Repo Rollout Map (Phase 0-3) <a class="header-anchor" href="#cross-repo-rollout-map-phase-0-3" aria-label="Permalink to &quot;Cross-Repo Rollout Map (Phase 0-3)&quot;">​</a></h1><p>Date: 2026-02-26 Scope: Align <code>heliosApp</code>, <code>heliosCLI</code>, <code>thegent</code>, <code>trace</code>, <code>heliosHarness</code> for long-running multi-tenant MAS swarms.</p><h2 id="repo-ownership-and-responsibilities" tabindex="-1">Repo Ownership and Responsibilities <a class="header-anchor" href="#repo-ownership-and-responsibilities" aria-label="Permalink to &quot;Repo Ownership and Responsibilities&quot;">​</a></h2><ul><li><p><code>heliosApp</code>:</p><ul><li>Desktop UX shell (ElectroBun)</li><li>Terminal-first runtime client</li><li>Renderer switching (<code>ghostty</code>/<code>rio</code>)</li><li>Lane/session UI orchestration and approvals</li></ul></li><li><p><code>heliosCLI</code>:</p><ul><li>Local developer entrypoint</li><li>CLI commands for runtime operations and protocol diagnostics</li><li>Headless/automation interfaces for local operator workflows</li></ul></li><li><p><code>thegent</code>:</p><ul><li>Swarm planner/router</li><li>Provider routing, policy gates, agent lifecycle orchestration</li><li>ACP/MCP/A2A adapters at agent boundary</li></ul></li><li><p><code>trace</code>:</p><ul><li>Durable workflow and governance substrate</li><li>Temporal workflows, workflow observability, evidence and audit APIs</li><li>Compliance and traceability views for swarm runs</li></ul></li><li><p><code>heliosHarness</code>:</p><ul><li>Optimization dashboard</li><li>Pareto and ledger visibility</li><li>NATS/JetStream-driven telemetry views and tuning insights</li></ul></li></ul><h2 id="phase-0-contract-freeze-and-baseline-1-2-weeks" tabindex="-1">Phase 0: Contract Freeze and Baseline (1-2 weeks) <a class="header-anchor" href="#phase-0-contract-freeze-and-baseline-1-2-weeks" aria-label="Permalink to &quot;Phase 0: Contract Freeze and Baseline (1-2 weeks)&quot;">​</a></h2><h3 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h3><ul><li>Freeze protocol and event contracts across repos.</li><li>Establish baseline integration test matrix.</li><li>Ensure consistent IDs and correlation conventions.</li></ul><h3 id="deliverables" tabindex="-1">Deliverables <a class="header-anchor" href="#deliverables" aria-label="Permalink to &quot;Deliverables&quot;">​</a></h3><ul><li><code>helios.localbus.v1</code> envelope schema and method/topic catalog.</li><li>cross-repo ID standards: <ul><li><code>workspace_id</code></li><li><code>lane_id</code></li><li><code>session_id</code></li><li><code>terminal_id</code></li><li><code>run_id</code></li><li><code>correlation_id</code></li></ul></li></ul><h3 id="api-event-contracts" tabindex="-1">API/Event contracts <a class="header-anchor" href="#api-event-contracts" aria-label="Permalink to &quot;API/Event contracts&quot;">​</a></h3><ul><li>Contract C0-1 (<code>heliosApp</code> &lt;-&gt; <code>thegent</code>): <ul><li>command API: <code>agent.run</code>, <code>agent.cancel</code>, <code>approval.request.resolve</code></li></ul></li><li>Contract C0-2 (<code>thegent</code> &lt;-&gt; <code>trace</code>): <ul><li>workflow start/status/result endpoints for durable runs</li></ul></li><li>Contract C0-3 (<code>thegent</code>/<code>trace</code> -&gt; <code>heliosHarness</code>): <ul><li>telemetry topics and metric schema over NATS/JetStream</li></ul></li></ul><h2 id="phase-1-local-first-runtime-integration-2-4-weeks" tabindex="-1">Phase 1: Local-First Runtime Integration (2-4 weeks) <a class="header-anchor" href="#phase-1-local-first-runtime-integration-2-4-weeks" aria-label="Permalink to &quot;Phase 1: Local-First Runtime Integration (2-4 weeks)&quot;">​</a></h2><h3 id="goals-1" tabindex="-1">Goals <a class="header-anchor" href="#goals-1" aria-label="Permalink to &quot;Goals&quot;">​</a></h3><ul><li>Deliver end-to-end local flow with lane lifecycle and terminal mux.</li><li>Keep distributed complexity behind feature toggles.</li></ul><h3 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h3><ul><li><code>heliosApp</code>: lane/session UI + renderer path</li><li><code>heliosCLI</code>: local command surfaces</li><li><code>thegent</code>: lane orchestration + provider adapters</li></ul><h3 id="api-event-contracts-1" tabindex="-1">API/Event contracts <a class="header-anchor" href="#api-event-contracts-1" aria-label="Permalink to &quot;API/Event contracts&quot;">​</a></h3><ul><li>Contract P1-1 Lane lifecycle: <ul><li>commands: <code>lane.create</code>, <code>lane.attach</code>, <code>lane.cleanup</code></li><li>events: <code>lane.created</code>, <code>lane.cleaned</code></li></ul></li><li>Contract P1-2 Terminal lifecycle: <ul><li>commands: <code>terminal.spawn</code>, <code>terminal.input</code>, <code>terminal.resize</code></li><li>events: <code>terminal.spawned</code>, <code>terminal.output</code>, <code>terminal.state.changed</code></li></ul></li><li>Contract P1-3 Collaboration lifecycle: <ul><li>commands: <code>share.upterm.start/stop</code>, <code>share.tmate.start/stop</code></li><li>events: <code>share.session.started/stopped</code></li></ul></li></ul><h2 id="phase-2-durable-multi-tenant-workflows-3-6-weeks" tabindex="-1">Phase 2: Durable Multi-Tenant Workflows (3-6 weeks) <a class="header-anchor" href="#phase-2-durable-multi-tenant-workflows-3-6-weeks" aria-label="Permalink to &quot;Phase 2: Durable Multi-Tenant Workflows (3-6 weeks)&quot;">​</a></h2><h3 id="goals-2" tabindex="-1">Goals <a class="header-anchor" href="#goals-2" aria-label="Permalink to &quot;Goals&quot;">​</a></h3><ul><li>Make long-running swarm tasks durable and resumable via Temporal.</li><li>Add tenant isolation and policy-aware workflow controls.</li></ul><h3 id="ownership-1" tabindex="-1">Ownership <a class="header-anchor" href="#ownership-1" aria-label="Permalink to &quot;Ownership&quot;">​</a></h3><ul><li><code>trace</code>: Temporal workflow definitions, workers, workflow APIs</li><li><code>thegent</code>: workflow intent submission and checkpoint integration</li><li><code>heliosApp</code>/<code>heliosCLI</code>: user-facing workflow controls and status displays</li></ul><h3 id="api-event-contracts-2" tabindex="-1">API/Event contracts <a class="header-anchor" href="#api-event-contracts-2" aria-label="Permalink to &quot;API/Event contracts&quot;">​</a></h3><ul><li>Contract P2-1 Workflow submission (<code>thegent</code> -&gt; <code>trace</code>): <ul><li><code>POST /workflows/run</code></li><li>payload: tenant, lane, task spec, policy context</li></ul></li><li>Contract P2-2 Workflow state stream (<code>trace</code> -&gt; consumers): <ul><li>workflow state events (<code>queued</code>, <code>running</code>, <code>retrying</code>, <code>awaiting_approval</code>, <code>completed</code>, <code>failed</code>)</li><li>includes <code>workflow_id</code>, <code>run_id</code>, <code>correlation_id</code></li></ul></li><li>Contract P2-3 Checkpoint/recovery: <ul><li><code>thegent</code> maps Temporal checkpoints to lane/session state</li><li><code>heliosApp</code> renders recovery prompt/actions</li></ul></li></ul><h2 id="phase-3-distributed-portability-optimization-plane-4-8-weeks" tabindex="-1">Phase 3: Distributed Portability + Optimization Plane (4-8 weeks) <a class="header-anchor" href="#phase-3-distributed-portability-optimization-plane-4-8-weeks" aria-label="Permalink to &quot;Phase 3: Distributed Portability + Optimization Plane (4-8 weeks)&quot;">​</a></h2><h3 id="goals-3" tabindex="-1">Goals <a class="header-anchor" href="#goals-3" aria-label="Permalink to &quot;Goals&quot;">​</a></h3><ul><li>Add Dapr portability for service invocation/pubsub/state binding where needed.</li><li>Expose optimization and policy health surfaces in <code>heliosHarness</code>.</li></ul><h3 id="ownership-2" tabindex="-1">Ownership <a class="header-anchor" href="#ownership-2" aria-label="Permalink to &quot;Ownership&quot;">​</a></h3><ul><li><code>thegent</code> + <code>trace</code>: Dapr-enabled service edges and pubsub bindings</li><li><code>heliosHarness</code>: metrics aggregation and Pareto/ledger optimization UI</li><li><code>heliosApp</code>/<code>heliosCLI</code>: operator controls and surfaced diagnostics</li></ul><h3 id="api-event-contracts-3" tabindex="-1">API/Event contracts <a class="header-anchor" href="#api-event-contracts-3" aria-label="Permalink to &quot;API/Event contracts&quot;">​</a></h3><ul><li>Contract P3-1 Service invocation: <ul><li>typed service endpoints for workflow and policy operations</li><li>Dapr sidecar invocation where portability is needed</li></ul></li><li>Contract P3-2 Event backbone: <ul><li>NATS/JetStream canonical topics remain source for telemetry fanout</li><li>Dapr pubsub bridge optional where deployment model requires it</li></ul></li><li>Contract P3-3 Optimization loop: <ul><li><code>heliosHarness</code> consumes run telemetry, cost, latency, success metrics</li><li>emits recommended routing/policy adjustments back to <code>thegent</code></li></ul></li></ul><h2 id="canonical-event-topics-cross-repo" tabindex="-1">Canonical Event Topics (Cross-Repo) <a class="header-anchor" href="#canonical-event-topics-cross-repo" aria-label="Permalink to &quot;Canonical Event Topics (Cross-Repo)&quot;">​</a></h2><ul><li><code>helios.lane.created</code></li><li><code>helios.lane.cleaned</code></li><li><code>helios.session.attached</code></li><li><code>helios.terminal.output</code></li><li><code>helios.agent.run.started</code></li><li><code>helios.agent.run.progress</code></li><li><code>helios.agent.run.completed</code></li><li><code>helios.agent.run.failed</code></li><li><code>helios.approval.requested</code></li><li><code>helios.approval.resolved</code></li><li><code>helios.workflow.state.changed</code></li><li><code>helios.audit.recorded</code></li><li><code>helios.policy.denied</code></li></ul><h2 id="api-surface-minimum" tabindex="-1">API Surface (Minimum) <a class="header-anchor" href="#api-surface-minimum" aria-label="Permalink to &quot;API Surface (Minimum)&quot;">​</a></h2><ul><li><p><code>thegent</code> APIs:</p><ul><li><code>POST /api/v1/lane/create</code></li><li><code>POST /api/v1/lane/cleanup</code></li><li><code>POST /api/v1/agent/run</code></li><li><code>POST /api/v1/agent/cancel</code></li></ul></li><li><p><code>trace</code> APIs:</p><ul><li><code>POST /api/v1/workflows/run</code></li><li><code>GET /api/v1/workflows/{id}</code></li><li><code>GET /api/v1/workflows/{id}/events</code></li><li><code>GET /api/v1/temporal/summary</code></li></ul></li><li><p><code>heliosHarness</code> APIs:</p><ul><li><code>GET /api/v1/metrics/pareto</code></li><li><code>GET /api/v1/metrics/ledger</code></li><li><code>POST /api/v1/recommendations/apply</code></li></ul></li></ul><h2 id="non-negotiable-rules" tabindex="-1">Non-Negotiable Rules <a class="header-anchor" href="#non-negotiable-rules" aria-label="Permalink to &quot;Non-Negotiable Rules&quot;">​</a></h2><ol><li>Local PTY hot path remains independent from distributed orchestration stack.</li><li>All cross-repo operations include <code>correlation_id</code> and <code>tenant_id</code>.</li><li>Policy checks execute before remote workflow dispatch.</li><li>Any cross-repo failure must degrade gracefully to lane-level failure, not global runtime crash.</li></ol><h2 id="exit-criteria-by-phase" tabindex="-1">Exit Criteria by Phase <a class="header-anchor" href="#exit-criteria-by-phase" aria-label="Permalink to &quot;Exit Criteria by Phase&quot;">​</a></h2><ul><li>Phase 0: <ul><li>contract docs frozen and reviewed across repo owners</li></ul></li><li>Phase 1: <ul><li>local lane/session flow stable with 25 terminals</li></ul></li><li>Phase 2: <ul><li>durable workflow resume/retry/human-approval loops working via Temporal</li></ul></li><li>Phase 3: <ul><li>Dapr portability path and optimization feedback loop operational</li></ul></li></ul>',40)])])}const m=o(t,[["render",r]]);export{p as __pageData,m as default};
